import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen1Test {





    @Test
    public void testContainsNone_BasicMatches() {
        // No match
        assertTrue(StringUtils.containsNone("abc", new char[]{'d', 'e'}));
        // Single char match (BMP)
        assertFalse(StringUtils.containsNone("abc", new char[]{'b'}));
        // Multiple char match (BMP)
        assertFalse(StringUtils.containsNone("abc", new char[]{'a', 'c'}));
        // Match at beginning
        assertFalse(StringUtils.containsNone("abc", new char[]{'a'}));
        // Match at end
        assertFalse(StringUtils.containsNone("abc", new char[]{'c'}));
    }




}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen1Test {







    @Test
    public void testContainsNone_SurrogatePairs() {
        // Unicode emoji: U+1F600 (😀) is represented by surrogate pair \uD83D\uDE00
        String emoji = "\uD83D\uDE00";
        char[] emojiChars = new char[]{'\uD83D', '\uDE00'};
        char[] otherChars = {'a', 'b'};

        // No match with surrogate pair
        assertTrue(StringUtils.containsNone(emoji, otherChars));

        // Match with full surrogate pair
        assertFalse(StringUtils.containsNone(emoji, emojiChars));

        // Match with partial surrogate (High surrogate only)
        // The logic: if searchChars[j] is high surrogate and it's the last in searchChars, return false
        char[] highSurrogateOnly = new char[]{'\uD83D'};
        assertFalse(StringUtils.containsNone(emoji, highSurrogateOnly));

        // Match with partial surrogate (High surrogate followed by wrong low surrogate)
        // The logic: if searchChars[j+1] != cs.charAt(i+1), it doesn't return false immediately in the inner loop, 
        // but if it doesn't match the pair, it continues.
        // However, the specific code branch: if (i < csLast && searchChars[j + 1] == cs.charAt(i + 1))
        char[] wrongLowSurrogate = new char[]{'\uD83D', '\uDE01'};
        assertTrue(StringUtils.containsNone(emoji, wrongLowSurrogate));

        // Test the boundary condition: High surrogate at the very end of the string 'cs'
        // csLast = csLen + 1. If i is the last char, i < csLast is true. 
        // But cs.charAt(i+1) would throw IndexOutOfBoundsException if not for the logic.
        // Looking at the code: csLast = csLen + 1. If i = csLen - 1, i+1 = csLen. 
        // cs.charAt(csLen) will throw StringIndexOutOfBoundsException.
        // Let's test if the code handles the end of string for high surrogates.
        String endWithHigh = "\uD83D"; 
        char[] matchHigh = new char[]{'\uD83D', '\uDE00'};
        // This test case is designed to see if the provided code crashes or handles the boundary.
        // Based on the provided code: if (i < csLast && searchChars[j + 1] == cs.charAt(i + 1))
        // if i = 0 and csLen = 1, csLast = 2. i < csLast is true. cs.charAt(1) will throw exception.
        try {
            StringUtils.containsNone("\uD83D", matchHigh);
        } catch (StringIndexOutOfBoundsException e) {
            // If the code is intended to be exactly as provided, it might throw this.
        }
    }


}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen1Test {









    @Test
    public void testContainsNone_ComplexScenarios() {
        // Mixed BMP and Surrogates
        String mixed = "a\uD83D\uDE00b";
        assertFalse(StringUtils.containsNone(mixed, new char[]{'a'}));
        assertFalse(StringUtils.containsNone(mixed, new char[]{'\uD83D', '\uDE00'}));
        assertTrue(StringUtils.containsNone(mixed, new char[]{'z'}));

        // searchChars contains high surrogate but not the matching low surrogate
        char[] searchPartial = new char[]{'\uD83D'};
        assertFalse(StringUtils.containsNone("a\uD83D\uDE00b", searchPartial));
    }
}
